261:     Class<?> optsType = parser.getOptsType();
262:     String contentType = parser.getContentType();
263: 
264:     if (requestContentType.equalsIgnoreCase(contentType) && optsType.isInstance(parse.getOpts())) {
265:       @SuppressWarnings("unchecked") Parser<O> castParser = (Parser<O>) parser;
266:       try {
267:         return castParser.parse(this, getRequest().getBody(), parse);
268:       } catch (Exception e) {
