309: 
310:     if (ifModifiedSinceHeader != null) {
311:       long time = ifModifiedSinceHeader.getTime();
312:       long ifModifiedSinceSecs = time / 1000;
313: 
314:       if (lastModifiedSecs == ifModifiedSinceSecs) {
315:         requestConstants.response.status(NOT_MODIFIED.code(), NOT_MODIFIED.reasonPhrase()).send();
316:         return;
317:       }
318:     }
