336:     } catch (Exception errorHandlerException) {
337:       StringWriter stringWriter = new StringWriter();
338:       PrintWriter printWriter = new PrintWriter(stringWriter);
339:       stringWriter.
340:         append("Exception thrown by error handler ").
341:         append(serverErrorHandler.toString()).
342:         append(" while handling exception\nOriginal exception: ");
343:       unpacked.printStackTrace(printWriter);
344:       stringWriter.
345:         append("Error handler exception: ");
346:       errorHandlerException.printStackTrace(printWriter);
347:       LOGGER.warning(stringWriter.toString());
348:       requestConstants.response.status(500).send();
349:     }
350:   }
