388:       public void execute(Result<T> result) {
389:         if (result.isFailure()) {
390:           dispatchException(result.getFailure());
391:         } else {
392:           try {
393:             action.execute(result.getValue());
394:           } catch (Exception e) {
395:             dispatchException(e);
396:           }
397:         }
398:       }
399:     };
