410:   protected void doNext(Context parentContext, final Registry registry, final int nextIndex, final Handler[] nextHandlers, Handler exhausted) {
411:     Context context;
412:     Handler handler;
413: 
414:     if (nextIndex >= nextHandlers.length) {
415:       context = parentContext;
416:       handler = exhausted;
417:     } else {
418:       handler = nextHandlers[nextIndex];
419:       context = createContext(registry, nextHandlers, nextIndex + 1, exhausted);
420:     }
421: 
422:     try {
423:       handler.handle(context);
424:     } catch (Exception e) {
425:       if (e instanceof HandlerException) {
426:         throw (HandlerException) e;
427:       } else {
428:         throw new HandlerException(context, e);
429:       }
430:     }
431:   }
